INSERT INTO diagnosis_results (id, advices, prescription, description, symstoms_text, feed_back_ai, clinical_info, consultation_id, department, created_at, updated_at) VALUES
  ('f18613bc-5997-4e95-8848-ada7021b2240', 'Tránh chà xát mạnh vùng này vì dễ gây chảy máu khó cầm. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Gel làm dịu da Hirudoid", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 4, "concentration": "5%"}, {"name": "Dung dịch Povidine", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 5, "concentration": "10%"}]', 'Không có tình trạng xuất huyết dưới da nguy hiểm. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 91%.', '{"age": 33, "gender": "FEMALE", "allergy": "không", "genetic": "yes", "history": "không", "symptom": "Vùng da bị tấy đỏ", "duration": "3 ngày", "location": "lưng", "severity": "whole", "skinType": ["deep"]}', '98ca00ac-d69a-4666-a9a7-f05108ef9335', 'Dermatology', NOW(), NOW()),
  ('bb75f3e3-bbe3-4c44-ad83-82e01cd8db88', 'Tránh chà xát mạnh vùng này vì dễ gây chảy máu khó cầm. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem dưỡng phục hồi Cicaplast", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 1, "concentration": "tuýp"}, {"name": "Thuốc giảm đau Paracetamol", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "2 tuần", "quantity": 3, "concentration": "tuýp"}]', 'U máu anh đào (Cherry Angioma) lành tính. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Bệnh nhân cảm thấy lo lắng.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 96%.', '{"age": 47, "gender": "MALE", "allergy": "không", "genetic": "no", "history": "không", "symptom": "Vùng da bị tấy đỏ", "duration": "1 tháng", "location": "đùi", "severity": "whole", "skinType": ["surface"]}', 'd7267188-8669-4624-986e-9dfd31e5c995', 'Dermatology', NOW(), NOW()),
  ('32997e56-c243-4071-82e6-e9fb14da0af7', 'Bắt buộc sử dụng kem chống nắng phổ rộng mỗi khi ra ngoài. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "1 tuần", "quantity": 2, "concentration": "hộp"}, {"name": "Gel Diclofenac", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 3, "concentration": "500mg"}]', 'Biểu hiện dày sừng rõ rệt, cần theo dõi khả năng tiến triển thành SCC. Theo dõi thêm diễn tiến.', 'Bề mặt tổn thương đóng vảy khô, sờ vào thấy nhám như giấy nhám. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Dày sừng quang hóa (AKIEC). Độ tin cậy: 96%.', '{"age": 39, "gender": "MALE", "allergy": "kháng sinh", "genetic": "yes", "history": "nv", "symptom": "Nổi sần đỏ rát", "duration": "3 ngày", "location": "cánh tay", "severity": "spread", "skinType": ["other", "surface"]}', '89ebcb17-22be-450f-a3c6-3c6865cc9758', 'Dermatology', NOW(), NOW()),
  ('da70b763-e70c-4cd9-91e4-760bf444e783', 'Nên mặc áo dài tay và đội mũ rộng vành để bảo vệ vùng da tổn thương. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem dưỡng phục hồi Cicaplast", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 4, "concentration": "vỉ"}, {"name": "Thuốc giảm đau Paracetamol", "dosage": "Bôi một lớp mỏng", "duration": "1 tuần", "quantity": 5, "concentration": "hộp"}, {"name": "Kem bôi giảm ngứa", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "2 tuần", "quantity": 4, "concentration": "vỉ"}]', 'Tổn thương tiền ung thư da do tác hại tích lũy của tia UV. Theo dõi thêm diễn tiến.', 'Bề mặt tổn thương đóng vảy khô, sờ vào thấy nhám như giấy nhám. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Dày sừng quang hóa (AKIEC). Độ tin cậy: 95%.', '{"age": 35, "gender": "FEMALE", "allergy": "hải sản", "genetic": "no", "history": "viêm da cơ địa", "symptom": "Vùng da bị tấy đỏ", "duration": "1 tuần", "location": "mặt", "severity": "whole", "skinType": ["surface"]}', '7cac1e4e-d6a5-4157-8137-9702267a49cb', 'Dermatology', NOW(), NOW()),
  ('edb5cb65-6991-4a21-a43b-fe0ee3a4fa0e', 'Cần thực hiện xét nghiệm sinh thiết để xác định chính xác loại tế bào. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Efudix", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 2, "concentration": "hộp"}, {"name": "Sữa tắm dịu nhẹ Cetaphil", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "hộp"}, {"name": "Dung dịch Povidine", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 5, "concentration": "10%"}]', 'Khối u phát triển chậm, xâm lấn tại chỗ, chưa có dấu hiệu di căn xa. Theo dõi thêm diễn tiến.', 'Tổn thương có bờ gồ cao, ở giữa hơi lõm xuống. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Ung thư biểu mô tế bào đáy (BCC). Độ tin cậy: 93%.', '{"age": 49, "gender": "FEMALE", "allergy": "thời tiết", "genetic": "no", "history": "không", "symptom": "Tôi bị mẫn ngứa nhiều ngày", "duration": "1 tuần", "location": "mặt", "severity": "local", "skinType": ["surface", "deep", "other"]}', 'dcbf0d98-a6ee-4840-8e20-0dbd664ac326', 'Dermatology', NOW(), NOW()),
  ('2250d3b1-b538-41ab-833e-07d0c85c58e4', 'Không nên tự ý tẩy bằng axit tại nhà vì dễ để lại sẹo lõm. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Uống 1 viên sau khi ăn no", "duration": "1 tuần", "quantity": 3, "concentration": "tuýp"}, {"name": "Dung dịch Povidine", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "500mg"}]', 'Tổn thương dày sừng tiết bã lành tính liên quan đến tuổi tác. Theo dõi thêm diễn tiến.', 'Kích thước tăng dần theo thời gian nhưng không gây đau nhức. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Dày sừng tiết bã (BKL). Độ tin cậy: 98%.', '{"age": 60, "gender": "MALE", "allergy": "kháng sinh", "genetic": "yes", "history": "nv", "symptom": "Da bong vảy khô", "duration": "3 ngày", "location": "toàn thân", "severity": "local", "skinType": ["surface", "deep"]}', '3aaa66e7-ebdd-4b82-86d8-1917e25139d3', 'Dermatology', NOW(), NOW()),
  ('ed9e4570-4bd5-4300-a2b8-5fdedcbe6915', 'Gia đình cần kiểm tra lại các nốt ruồi bất thường của các thành viên khác. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem chống nắng SPF 50+", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 5, "concentration": "hộp"}, {"name": "Kem dưỡng phục hồi Cicaplast", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 2, "concentration": "hộp"}, {"name": "Dung dịch Povidine", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 4, "concentration": "10%"}]', 'Tổn thương có các yếu tố nguy cơ cao theo quy tắc ABCDE. Theo dõi thêm diễn tiến.', 'Kích thước tăng nhanh trong vài tháng gần đây, có hiện tượng ngứa nhẹ. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là U hắc tố ác tính (MEL). Độ tin cậy: 91%.', '{"age": 47, "gender": "FEMALE", "allergy": "không", "genetic": "yes", "history": "viêm da cơ địa", "symptom": "Tôi bị mẫn ngứa nhiều ngày", "duration": "1 tuần", "location": "cánh tay", "severity": "local", "skinType": ["deep"]}', '005637f4-816e-4268-9ac9-70fa5e97c1e4', 'Dermatology', NOW(), NOW()),
  ('f90094ec-7fdb-4e59-af38-5f92b1838105', 'Có thể điều trị bằng laser thẩm mỹ nếu muốn xóa bỏ hoàn toàn. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "500mg"}, {"name": "Dưỡng thể làm dịu da", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 4, "concentration": "5%"}]', 'Các tổn thương giãn mạch do lão hóa da tự nhiên. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 98%.', '{"age": 21, "gender": "MALE", "allergy": "kháng sinh", "genetic": "no", "history": "nv", "symptom": "Nổi sần đỏ rát", "duration": "vài ngày", "location": "đùi", "severity": "spread", "skinType": ["surface", "other", "deep"]}', '97f14091-c251-4fa6-b4f1-687a23e2e8b1', 'Dermatology', NOW(), NOW()),
  ('6bff12c9-ae38-447f-bd77-cbb50763e9d7', 'Gia đình cần kiểm tra lại các nốt ruồi bất thường của các thành viên khác. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Efudix", "dosage": "Bôi một lớp mỏng", "duration": "10 ngày", "quantity": 4, "concentration": "10%"}, {"name": "Thuốc giảm đau Paracetamol", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "2 tuần", "quantity": 2, "concentration": "hộp"}]', 'Tổn thương có các yếu tố nguy cơ cao theo quy tắc ABCDE. Theo dõi thêm diễn tiến.', 'Nốt ruồi có hình dạng bất đối xứng, bờ không đều và nham nhở. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là U hắc tố ác tính (MEL). Độ tin cậy: 94%.', '{"age": 38, "gender": "MALE", "allergy": "hải sản", "genetic": "no", "history": "không", "symptom": "Nổi sần đỏ rát", "duration": "1 tuần", "location": "toàn thân", "severity": "local", "skinType": ["other", "surface", "deep"]}', 'c39d63ad-143d-4e19-956b-05006e386999', 'Dermatology', NOW(), NOW()),
  ('abb278a7-2d56-4f0e-928c-ea09ee486d1b', 'Gia đình cần kiểm tra lại các nốt ruồi bất thường của các thành viên khác. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 3, "concentration": "vỉ"}, {"name": "Mỡ kháng sinh Fucidin", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 5, "concentration": "500mg"}]', 'Tổn thương có các yếu tố nguy cơ cao theo quy tắc ABCDE. Theo dõi thêm diễn tiến.', 'Nốt ruồi có hình dạng bất đối xứng, bờ không đều và nham nhở. Bệnh nhân cảm thấy lo lắng.', 'AI phân tích: Khả năng cao là U hắc tố ác tính (MEL). Độ tin cậy: 92%.', '{"age": 62, "gender": "FEMALE", "allergy": "không", "genetic": "yes", "history": "viêm da cơ địa", "symptom": "Vùng da bị tấy đỏ", "duration": "vài ngày", "location": "đùi", "severity": "whole", "skinType": ["surface"]}', '46dc6402-be26-44b9-ac7f-d91a46d13700', 'Dermatology', NOW(), NOW()),
  ('603d4e0f-19e2-42df-9ca6-fdcaa1fea599', 'Có thể điều trị bằng laser thẩm mỹ nếu muốn xóa bỏ hoàn toàn. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem bôi Imiquimod", "dosage": "Bôi một lớp mỏng", "duration": "1 tuần", "quantity": 4, "concentration": "tuýp"}, {"name": "Mỡ kháng sinh Fucidin", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 5, "concentration": "hộp"}]', 'Các tổn thương giãn mạch do lão hóa da tự nhiên. Theo dõi thêm diễn tiến.', 'Xuất hiện các đốm đỏ tươi (u máu hình nhện) hoặc các sẩn màu tím sẫm. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 95%.', '{"age": 46, "gender": "MALE", "allergy": "kháng sinh", "genetic": "no", "history": "nv", "symptom": "Nốt ruồi có dấu hiệu ngứa", "duration": "1 tuần", "location": "cánh tay", "severity": "spread", "skinType": ["surface", "deep"]}', 'de1d55b0-cfbd-4bab-8fc5-89e6b116bc3f', 'Dermatology', NOW(), NOW()),
  ('78169daa-13e9-4ff2-a8d5-6930d9451287', 'Nếu thấy nốt nào ngứa, chảy máu hoặc đổi màu thì phải đi khám ngay. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem chống nắng SPF 50+", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "500mg"}, {"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 4, "concentration": "tuýp"}, {"name": "Kem bôi Imiquimod", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 5, "concentration": "500mg"}]', 'Tình trạng da bình thường, không cần can thiệp y tế. Theo dõi thêm diễn tiến.', 'Bề mặt phẳng hoặc hơi gồ cao, không đau không ngứa. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Nốt ruồi lành tính (NV). Độ tin cậy: 95%.', '{"age": 27, "gender": "MALE", "allergy": "hải sản", "genetic": "yes", "history": "nv", "symptom": "Tôi bị mẫn ngứa nhiều ngày", "duration": "1 tháng", "location": "đùi", "severity": "spread", "skinType": ["other"]}', '62310e3e-035d-459e-8395-635a54e92524', 'Dermatology', NOW(), NOW()),
  ('01fb6b36-2b4a-456a-9d39-465c49636d80', 'Hạn chế các tác động mạnh hoặc nặn bóp vào nốt sẩn. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Dung dịch sát khuẩn Betadine", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 2, "concentration": "tuýp"}, {"name": "Viên uống hỗ trợ da Vitamin E", "dosage": "Bôi một lớp mỏng", "duration": "10 ngày", "quantity": 4, "concentration": "5%"}, {"name": "Gel Diclofenac", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 1, "concentration": "10%"}]', 'Dấu hiệu Fitzpatrick dương tính điển hình của u xơ da. Theo dõi thêm diễn tiến.', 'Khi bóp nhẹ hai bên, nốt sẩn có xu hướng lúm xuống ở giữa. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là U xơ da (DF). Độ tin cậy: 93%.', '{"age": 60, "gender": "FEMALE", "allergy": "hải sản", "genetic": "no", "history": "không", "symptom": "Da bong vảy khô", "duration": "vài ngày", "location": "cánh tay", "severity": "local", "skinType": ["surface", "deep"]}', 'a3befac7-6705-4e58-8543-686b79a5997f', 'Dermatology', NOW(), NOW()),
  ('e45d8d1d-2501-485d-b6de-a7385f02971d', 'Tránh chà xát mạnh vùng này vì dễ gây chảy máu khó cầm. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống bền thành mạch Vitamin C", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 5, "concentration": "hộp"}, {"name": "Gel Diclofenac", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 2, "concentration": "5%"}, {"name": "Sữa tắm dịu nhẹ Cetaphil", "dosage": "Bôi một lớp mỏng", "duration": "1 tuần", "quantity": 2, "concentration": "tuýp"}]', 'Không có tình trạng xuất huyết dưới da nguy hiểm. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Bệnh nhân cảm thấy lo lắng.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 93%.', '{"age": 18, "gender": "FEMALE", "allergy": "hải sản", "genetic": "yes", "history": "bkl", "symptom": "Tôi bị mẫn ngứa nhiều ngày", "duration": "vài ngày", "location": "toàn thân", "severity": "local", "skinType": ["other"]}', 'dc74eb14-7c6c-40c3-b92b-cf062a2abeb7', 'Dermatology', NOW(), NOW()),
  ('064c5134-5db2-4f19-8793-863e2d4b9b6e', 'Không cần điều trị can thiệp trừ khi gây đau hoặc khó chịu khi mặc quần áo. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Gel Diclofenac", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 4, "concentration": "500mg"}, {"name": "Kem làm mềm sừng chứa Urea", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 1, "concentration": "5%"}, {"name": "Gel làm dịu da Hirudoid", "dosage": "Uống 1 viên sau khi ăn no", "duration": "1 tuần", "quantity": 5, "concentration": "5%"}]', 'U xơ biểu mô lành tính vùng chân. Theo dõi thêm diễn tiến.', 'Nốt sẩn cứng dưới da, màu nâu hồng, sờ vào thấy chắc như hạt đậu. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là U xơ da (DF). Độ tin cậy: 91%.', '{"age": 50, "gender": "MALE", "allergy": "hải sản", "genetic": "yes", "history": "không", "symptom": "Vùng da bị tấy đỏ", "duration": "vài ngày", "location": "đùi", "severity": "whole", "skinType": ["surface", "deep"]}', 'a9be91e5-66da-4a0c-9217-6383e09a976b', 'Dermatology', NOW(), NOW()),
  ('b6e12572-9cb6-45a5-8c36-ce975b597123', 'Đây là tình trạng lành tính, không cần quá lo lắng. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Sữa tắm dịu nhẹ Cetaphil", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 5, "concentration": "5%"}, {"name": "Efudix", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 4, "concentration": "tuýp"}, {"name": "Kem chống nắng SPF 50+", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 4, "concentration": "10%"}]', 'Các sẩn sừng xuất hiện rải rác ở vùng lưng và ngực. Theo dõi thêm diễn tiến.', 'Các mảng sẫm màu có bề mặt gồ ghề, trông như sáp nến dán lên da. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Dày sừng tiết bã (BKL). Độ tin cậy: 93%.', '{"age": 63, "gender": "MALE", "allergy": "thời tiết", "genetic": "no", "history": "không", "symptom": "Nổi sần đỏ rát", "duration": "vài ngày", "location": "toàn thân", "severity": "spread", "skinType": ["other", "deep", "surface"]}', '683165e5-33ce-47f3-a98d-b3d6c25e0f92', 'Dermatology', NOW(), NOW()),
  ('283cb7c6-0d29-4443-8ad2-9c0d55c7257f', 'Tuyệt đối không được tác động bằng laser hoặc hóa chất tẩy nốt ruồi. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem bôi Imiquimod", "dosage": "Bôi một lớp mỏng", "duration": "10 ngày", "quantity": 4, "concentration": "hộp"}, {"name": "Gel Diclofenac", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 3, "concentration": "5%"}]', 'Tổn thương có các yếu tố nguy cơ cao theo quy tắc ABCDE. Theo dõi thêm diễn tiến.', 'Kích thước tăng nhanh trong vài tháng gần đây, có hiện tượng ngứa nhẹ. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là U hắc tố ác tính (MEL). Độ tin cậy: 91%.', '{"age": 44, "gender": "MALE", "allergy": "kháng sinh", "genetic": "no", "history": "viêm da cơ địa", "symptom": "Da bong vảy khô", "duration": "3 ngày", "location": "toàn thân", "severity": "local", "skinType": ["surface"]}', 'bcb7620b-7ba5-4662-bad8-54f9fa5a24f8', 'Dermatology', NOW(), NOW()),
  ('dfcfb3a6-2451-4a88-bfc9-f5f843251113', 'Hạn chế sử dụng các chất kích thích gây giãn mạch như rượu bia. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Viên uống hỗ trợ da Vitamin E", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "2 tuần", "quantity": 5, "concentration": "500mg"}, {"name": "Mỡ kháng sinh Fucidin", "dosage": "Bôi một lớp mỏng", "duration": "10 ngày", "quantity": 3, "concentration": "10%"}, {"name": "Sữa tắm dịu nhẹ Cetaphil", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "hộp"}]', 'U máu anh đào (Cherry Angioma) lành tính. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 92%.', '{"age": 40, "gender": "FEMALE", "allergy": "kháng sinh", "genetic": "yes", "history": "không", "symptom": "Da bong vảy khô", "duration": "3 ngày", "location": "lưng", "severity": "spread", "skinType": ["surface", "other"]}', '27b5e804-0a15-4e8e-a26a-cfa4b4d1884c', 'Dermatology', NOW(), NOW()),
  ('5397e011-835a-47e3-8d06-d5e7a94c3265', 'Theo dõi nếu có sự thay đổi đột ngột về màu sắc hoặc kích thước. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Gel Diclofenac", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 2, "concentration": "tuýp"}, {"name": "Dưỡng thể làm dịu da", "dosage": "Bôi một lớp mỏng", "duration": "10 ngày", "quantity": 4, "concentration": "10%"}]', 'Dấu hiệu Fitzpatrick dương tính điển hình của u xơ da. Theo dõi thêm diễn tiến.', 'Khi bóp nhẹ hai bên, nốt sẩn có xu hướng lúm xuống ở giữa. Bệnh nhân cảm thấy lo lắng.', 'AI phân tích: Khả năng cao là U xơ da (DF). Độ tin cậy: 95%.', '{"age": 58, "gender": "MALE", "allergy": "không", "genetic": "no", "history": "viêm da cơ địa", "symptom": "Da bong vảy khô", "duration": "3 ngày", "location": "lưng", "severity": "local", "skinType": ["deep"]}', '7fa97e4a-0cdf-4316-b64b-f10d8f82cc67', 'Dermatology', NOW(), NOW()),
  ('9902db08-47a0-4f4b-8452-dca1489ccd8b', 'Tái khám đúng hẹn để lên lịch phẫu thuật loại bỏ khối u. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem bôi Imiquimod", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 2, "concentration": "vỉ"}, {"name": "Dung dịch sát khuẩn Betadine", "dosage": "Bôi một lớp mỏng", "duration": "2 tuần", "quantity": 3, "concentration": "vỉ"}, {"name": "Kem bôi giảm ngứa", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 4, "concentration": "5%"}]', 'Nghi ngờ ung thư biểu mô tế bào đáy thể nốt. Theo dõi thêm diễn tiến.', 'Vết loét chậm lành, đôi khi rướm máu rồi đóng vảy lại. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Ung thư biểu mô tế bào đáy (BCC). Độ tin cậy: 97%.', '{"age": 15, "gender": "MALE", "allergy": "thời tiết", "genetic": "no", "history": "không", "symptom": "Nốt ruồi có dấu hiệu ngứa", "duration": "1 tháng", "location": "cánh tay", "severity": "local", "skinType": ["surface", "deep", "other"]}', '5e4651ed-8af7-4f5f-a228-ad370c4e10b1', 'Dermatology', NOW(), NOW()),
  ('71d7cf7e-7941-4c5e-b6bd-b782a6409630', 'Nên mặc áo dài tay và đội mũ rộng vành để bảo vệ vùng da tổn thương. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Kem làm mềm sừng chứa Urea", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 1, "concentration": "10%"}, {"name": "Gel làm dịu da Hirudoid", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "1 tuần", "quantity": 1, "concentration": "vỉ"}, {"name": "Kem chống nắng SPF 50+", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "1 tuần", "quantity": 2, "concentration": "10%"}]', 'Dày sừng quang hóa khu trú vùng mặt và mu bàn tay. Theo dõi thêm diễn tiến.', 'Bề mặt tổn thương đóng vảy khô, sờ vào thấy nhám như giấy nhám. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Dày sừng quang hóa (AKIEC). Độ tin cậy: 93%.', '{"age": 35, "gender": "FEMALE", "allergy": "kháng sinh", "genetic": "yes", "history": "viêm da cơ địa", "symptom": "Da bong vảy khô", "duration": "1 tháng", "location": "đùi", "severity": "whole", "skinType": ["other", "deep", "surface"]}', '845e611f-a547-44d7-a81d-c75aa75b356c', 'Dermatology', NOW(), NOW()),
  ('fa00bc66-d41f-42f5-a7e0-560d906a22fb', 'Đây là tình trạng lành tính, không cần quá lo lắng. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Thuốc giảm đau Paracetamol", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "1 tuần", "quantity": 4, "concentration": "10%"}, {"name": "Kem làm mềm sừng chứa Urea", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 3, "concentration": "500mg"}, {"name": "Gel Diclofenac", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "2 tuần", "quantity": 1, "concentration": "tuýp"}]', 'Tổn thương dày sừng tiết bã lành tính liên quan đến tuổi tác. Theo dõi thêm diễn tiến.', 'Thỉnh liên gây ngứa nhẹ khi đổ mồ hôi nhiều. Gây mất thẩm mỹ.', 'AI phân tích: Khả năng cao là Dày sừng tiết bã (BKL). Độ tin cậy: 92%.', '{"age": 45, "gender": "MALE", "allergy": "kháng sinh", "genetic": "no", "history": "viêm da cơ địa", "symptom": "Nốt ruồi có dấu hiệu ngứa", "duration": "3 ngày", "location": "đùi", "severity": "whole", "skinType": ["other", "surface", "deep"]}', '6b78b8b6-51d9-40d9-8bb2-41ff6b38fed4', 'Dermatology', NOW(), NOW()),
  ('15aeae08-231d-46f9-888e-f8fd071d335a', 'Chuẩn bị tâm lý để thực hiện phẫu thuật cắt rộng và kiểm tra hạch. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Dung dịch sát khuẩn Betadine", "dosage": "Uống 1 viên sau khi ăn no", "duration": "2 tuần", "quantity": 1, "concentration": "500mg"}, {"name": "Kem làm mềm sừng chứa Urea", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 5, "concentration": "hộp"}, {"name": "Viên uống hỗ trợ da Vitamin E", "dosage": "Uống 1 viên sau khi ăn no", "duration": "10 ngày", "quantity": 4, "concentration": "tuýp"}]', 'Tổn thương có các yếu tố nguy cơ cao theo quy tắc ABCDE. Theo dõi thêm diễn tiến.', 'Kích thước tăng nhanh trong vài tháng gần đây, có hiện tượng ngứa nhẹ. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là U hắc tố ác tính (MEL). Độ tin cậy: 92%.', '{"age": 42, "gender": "FEMALE", "allergy": "thời tiết", "genetic": "no", "history": "viêm da cơ địa", "symptom": "Tôi bị mẫn ngứa nhiều ngày", "duration": "3 ngày", "location": "đùi", "severity": "whole", "skinType": ["other"]}', 'bdd998d1-ef7e-4b52-bb21-f59e3125a909', 'Dermatology', NOW(), NOW()),
  ('6af77560-af3f-427a-a942-c1d0c213ffd9', 'Hạn chế sử dụng các chất kích thích gây giãn mạch như rượu bia. Liên hệ bác sĩ nếu có bất thường.', '[{"name": "Dung dịch sát khuẩn Betadine", "dosage": "Bôi 2 lần/ngày sáng và tối", "duration": "10 ngày", "quantity": 5, "concentration": "5%"}, {"name": "Gel làm dịu da Hirudoid", "dosage": "Bôi một lớp mỏng", "duration": "1 tuần", "quantity": 1, "concentration": "10%"}]', 'Các tổn thương giãn mạch do lão hóa da tự nhiên. Theo dõi thêm diễn tiến.', 'Đôi khi có hiện tượng giãn mạch li ti ở vùng cánh mũi hoặc má. Tình trạng kéo dài vài tuần.', 'AI phân tích: Khả năng cao là Tổn thương mạch máu (VASC). Độ tin cậy: 92%.', '{"age": 38, "gender": "FEMALE", "allergy": "hải sản", "genetic": "no", "history": "không", "symptom": "Da bong vảy khô", "duration": "vài ngày", "location": "lưng", "severity": "local", "skinType": ["other"]}', '21f50846-d8dc-4e07-a84f-1309706c666f', 'Dermatology', NOW(), NOW()),
